pub use ode::{BoundaryData,DifferentialSystem,FlowDiagnostics,FlowResult};
use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet};
use std::sync::Arc;
use std::time::Instant;
use symbolica::prelude::*;
use symbolica_amflow::algebraic::{CanonicalAlgebraicSystem, SquareRoot};
use algebraic::RootSeed;
pub use symbolica_amflow::{
    ComplexFloat, Error, FlowOptions, Precision, Prescription, Progress, Result, RunContext,
    kinematics,
};
fn atom(s: &str) -> Result<Atom> {
    Atom::parse(s, "fivepoint", Default::default()).map_err(|e| Error::InvalidInput(e.to_string()))
}
fn symbol(s: &str) -> Symbol {
    if let AtomView::Var(v) = atom(s).unwrap().as_view() {
        v.get_symbol()
    } else {
        panic!("symbol")
    }
}
fn scalar(p: Precision, v: &Value) -> Result<ComplexFloat> {
    p.parse(
        v["real"].as_str().unwrap(),
        v["imaginary"].as_str().unwrap(),
    )
}
fn encoded(v: &ComplexFloat) -> Value {
    json!({"real":v.re.to_string(),"imaginary":v.im.to_string()})
}
fn maximum_error(p: Precision, values: &[Vec<ComplexFloat>], reference: &Value) -> Result<Float> {
    let mut maximum = p.real(0);
    for (k, row) in values.iter().enumerate() {
        for (j, v) in row.iter().enumerate() {
            let e = p.norm(&p.sub(v, &scalar(p, &reference[k][j])?));
            if e > maximum {
                maximum = e;
            }
        }
    }
    Ok(maximum)
}
fn main() -> Result<()> {
    let args = std::env::args().collect::<Vec<_>>();
    let digits = args.get(1).map(|x| x.parse::<u32>().unwrap()).unwrap_or(60);
    let order = args
        .get(2)
        .map(|x| x.parse::<usize>().unwrap())
        .unwrap_or(80);

    let mode = args.get(3).map(String::as_str).unwrap_or("prepare");
    let fixture_path = args.get(4).map(String::as_str).unwrap_or(
        "/common/dev/amflow/target/diffexp-oracle/fivepoint-planar-zmz/full-native-input.json",
    );
    let fixture: Value =
        serde_json::from_str(&std::fs::read_to_string(fixture_path).unwrap()).unwrap();

    assert_eq!((digits,order),(60,56));
    let p = Precision::decimal(digits)?;
    let dimension = fixture["dimension"].as_u64().unwrap() as usize;
    let start_clock = Instant::now();
    let parameter = symbol("x");
    let epsilon = symbol("eps");
    let variables = fixture["coordinate_names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| symbol(n.as_str().unwrap()))
        .collect::<Vec<_>>();
    let mut coordinates = BTreeMap::new();
    for name in fixture["coordinate_names"].as_array().unwrap() {
        let name = name.as_str().unwrap();
        let a = atom(fixture["source_point"][name].as_str().unwrap())?;
        let b = atom(fixture["destination_point"][name].as_str().unwrap())?;
        coordinates.insert(symbol(name), &a + (b - &a) * Atom::var(parameter));
    }
    let path = kinematics::KinematicPath {
        parameter,
        coordinates,
    };
    let used = fixture["sparse_rational_coefficients"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["indices"][0].as_u64().unwrap() as usize)
        .collect::<BTreeSet<_>>();
    let mut letters = Vec::new();
    let mut matrices = Vec::new();
    for index in used {
        letters.push(atom(fixture["letters"][index - 1].as_str().unwrap())?);
        let mut m = vec![vec![Atom::new(); dimension]; dimension];
        for entry in fixture["sparse_rational_coefficients"].as_array().unwrap() {
            let indices = entry["indices"].as_array().unwrap();
            if indices[0].as_u64().unwrap() as usize == index {
                m[indices[1].as_u64().unwrap() as usize - 1]
                    [indices[2].as_u64().unwrap() as usize - 1] =
                    atom(entry["coefficient"].as_str().unwrap())?;
            }
        }
        matrices.push(m);
    }
    let mut roots = Vec::new();
    for name in ["tr5", "sqrtG3", "sqrtG3nc"] {
        if fixture["root_definitions"].get(name).is_none() {
            continue;
        }
        let definition = fixture["root_definitions"][name].as_str().unwrap();
        let polynomial = definition
            .strip_prefix("sqrt(")
            .unwrap()
            .strip_suffix(')')
            .unwrap();
        roots.push(SquareRoot {
            symbol: symbol(name),
            radicand: atom(polynomial)?,
        });
    }
    eprintln!("construct canonical physical system, digits={digits},order={order}");
    let symbolic_clock = Instant::now();
    let preparation_clock = Instant::now();
    let canonical = CanonicalAlgebraicSystem::new(epsilon, &variables, &letters, &matrices, roots)?;
    let canonical_seconds = preparation_clock.elapsed().as_secs_f64();
    let source_guards = canonical
        .nonzero_conditions()
        .iter()
        .map(AtomCore::to_canonical_string)
        .collect::<Vec<_>>();
    let pulled = canonical.pullback(&path, 4)?;
    let pulled_guards = pulled
        .nonzero_conditions
        .iter()
        .map(AtomCore::to_canonical_string)
        .collect::<Vec<_>>();
    eprintln!(
        "canonical source guards {}, pulled guards {}; constructor {canonical_seconds}s",
        source_guards.len(),
        pulled_guards.len()
    );
    let symbolic_seconds = symbolic_clock.elapsed().as_secs_f64();
    eprintln!("symbolic pullback complete in {symbolic_seconds:.3}s");
    let compile_clock = Instant::now();
    let pulled = algebraic::AlgebraicSystem {
        system: diffexp::EpsilonSystem { variable: pulled.system.variable, matrices: pulled.system.matrices },
        roots: pulled.roots.into_iter().map(|r| algebraic::SquareRoot { symbol:r.symbol, radicand:r.radicand }).collect(),
        nonzero_conditions: pulled.nonzero_conditions,
    };
    let compiled = pulled.compile(p)?;
    let compile_seconds = compile_clock.elapsed().as_secs_f64();
    eprintln!(
        "compiled in {compile_seconds:.3}s with {} singularity candidates",
        compiled.singularities().len()
    );
    let checkpoint:Value=serde_json::from_slice(&std::fs::read("target/pole-step-growth/leg100/checkpoint-099.json")?).unwrap();
    let reference:Value=serde_json::from_slice(&std::fs::read("target/pole-step-growth/leg100/checkpoint-100.json")?).unwrap();
    assert_eq!(checkpoint["waypoint_index"],99);assert_eq!(reference["waypoint_index"],100);
    for record in [&checkpoint,&reference] { assert_eq!(record["digits"],digits);assert_eq!(record["order"],order); }
    let point=scalar(p,&checkpoint["point"])?;let target=scalar(p,&reference["point"])?;
    let coefficients=checkpoint["values_by_epsilon"].as_array().unwrap().iter().map(|row|row.as_array().unwrap().iter().map(|v|scalar(p,v)).collect::<Result<Vec<_>>>()).collect::<Result<Vec<_>>>()?;
    assert_eq!(coefficients.len(),5);assert!(coefficients.iter().all(|row|row.len()==75));
    let boundary=diffexp::EpsilonBoundary{point,leading:0,coefficients};
    let seeds=checkpoint["branch_roots"].as_array().unwrap().iter().map(|r|Ok((symbol(r["root"].as_str().unwrap()),RootSeed::Value(scalar(p,&r["value"])?)))).collect::<Result<BTreeMap<_,_>>>()?;
    let options=FlowOptions{digits:20,guard_digits:40,series_order:56,max_steps:20000,..Default::default()};
    let context=RunContext{progress:Some(Arc::new(|e|if let Progress::Step{index}=e {if index%25==0 {eprintln!("step {index}");}})),..Default::default()};
    assert!(mode=="baseline" || mode=="proposal");
    ode::POLE_GROWTH_CAP.store(mode=="proposal",std::sync::atomic::Ordering::Relaxed);
    let transport_started=Instant::now();
    let answer=compiled.transport(&boundary,std::slice::from_ref(&target),&seeds,&options,&context,false)?;
    let transport_seconds=transport_started.elapsed().as_secs_f64();
    let error=maximum_error(p,&answer.solution.coefficients,&reference["values_by_epsilon"])?;
    assert!(error<p.tolerance(20),"saved endpoint disagreement {error}");
    assert_eq!(answer.solution.point,target);
    let result=json!({"status":"passed_supplied_checkpoint_comparison","controller":mode,"digits":digits,"order":order,"max_steps":options.max_steps,"symbolic_seconds":symbolic_seconds,"compile_seconds":compile_seconds,"transport_seconds":transport_seconds,"chart_nanoseconds":ode::CHART_NANOSECONDS.load(std::sync::atomic::Ordering::Relaxed),"chart_calls":ode::CHART_CALLS.load(std::sync::atomic::Ordering::Relaxed),"accepted":answer.solution.diagnostics.steps,"rejected":answer.solution.diagnostics.rejected_steps,"max_absolute_saved_endpoint_error":error.to_string(),"source_point":encoded(&boundary.point),"endpoint":encoded(&target),"values_by_epsilon":answer.solution.coefficients.iter().map(|r|r.iter().map(encoded).collect::<Vec<_>>()).collect::<Vec<_>>(),"branch_endpoint":answer.branches.roots.iter().map(|(r,v)|json!({"root":Atom::var(*r).to_string(),"value":encoded(v)})).collect::<Vec<_>>(),"source_guards":source_guards,"pulled_guards":pulled_guards,"wall_seconds":start_clock.elapsed().as_secs_f64()});
    println!("{}",serde_json::to_string_pretty(&result).unwrap());
    Ok(())
}
